    --warn: #b25e09;     --warn-soft: #fbf0e0;
    --info: #1f6feb;     --info-soft: #e7f0fd;
    --danger: #c4344b;   --danger-soft: #fbe6ea;
  }
  @media (prefers-color-scheme: dark) {
    :root {
      --bg: #0b0b10; --surface: #15151c; --fg: #f4f4f7; --fg-soft: #c8c8d0; --muted: #8a8a96;
      --rule: #25252e; --rule-soft: #1c1c24; --accent: #8b7cff; --accent-soft: #2a2548;
      --ok: #4fc28a; --ok-soft: #1a2e25; --warn: #e08a3a; --warn-soft: #2f2418;
      --info: #6ea8fe; --info-soft: #1a2538; --danger: #e87085; --danger-soft: #2c1820;
    }
