1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>Implementation plan — Comment threads on task cards</title>
7	  <style>
8	    :root {
9	      --ivory:    #FAF9F5;
10	      --slate:    #141413;
11	      --clay:     #D97757;
12	      --oat:      #E3DACC;
13	      --olive:    #788C5D;
14	      --gray-150: #F0EEE6;
15	      --gray-300: #D1CFC5;
16	      --gray-500: #87867F;
17	      --gray-700: #3D3D3A;
18	      --white:    #FFFFFF;
19	
20	      --serif: ui-serif, Georgia, 'Times New Roman', serif;
21	      --sans:  system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
22	      --mono:  ui-monospace, 'SF Mono', Menlo, Monaco, monospace;
23	    }
24	
25	    * { margin: 0; padding: 0; box-sizing: border-box; }
26	
27	    body {
28	      font-family: var(--sans);
29	      background: var(--ivory);
30	      color: var(--gray-700);
31	      line-height: 1.55;
32	      padding: 56px 32px 120px;
33	      -webkit-font-smoothing: antialiased;
34	    }
35	
36	    .page { max-width: 1120px; margin: 0 auto; }
37	
38	    /* ---------- header ---------- */
39	
40	    header.page-head { margin-bottom: 48px; max-width: 820px; }
41	
42	    .eyebrow {
43	      font-size: 12px;
44	      letter-spacing: 0.08em;
45	      text-transform: uppercase;
46	      color: var(--gray-500);
47	      margin-bottom: 12px;
48	    }
49	
50	    h1 {
51	      font-family: var(--serif);
52	      font-weight: 500;
53	      font-size: 38px;
54	      line-height: 1.15;
55	      color: var(--slate);
56	      margin-bottom: 18px;
57	      letter-spacing: -0.01em;
58	    }
59	
60	    .prompt-box {
61	      background: var(--gray-150);
62	      border: 1.5px solid var(--gray-300);
63	      border-radius: 12px;
64	      padding: 16px 20px;
65	      font-size: 14.5px;
66	      color: var(--gray-700);
67	    }
68	    .prompt-box .label {
69	      font-family: var(--mono);
70	      font-size: 11px;
71	      text-transform: uppercase;
72	      letter-spacing: 0.06em;
73	      color: var(--gray-500);
74	      display: block;
75	      margin-bottom: 6px;
76	    }
77	
78	    /* ---------- section chrome ---------- */
79	
80	    section { margin-bottom: 64px; }
81	
82	    .sec-head {
83	      display: flex;
84	      align-items: baseline;
85	      gap: 14px;
86	      margin-bottom: 8px;
87	    }
88	    .sec-head .num {
89	      font-family: var(--mono);
90	      font-size: 12px;
91	      background: var(--oat);
92	      color: var(--slate);
93	      padding: 3px 9px;
94	      border-radius: 8px;
95	    }
96	    .sec-head h2 {
97	      font-family: var(--serif);
98	      font-weight: 500;
99	      font-size: 26px;
100	      color: var(--slate);
101	      letter-spacing: -0.01em;
102	    }
103	    .sec-intro {
104	      font-size: 14.5px;
105	      color: var(--gray-500);
106	      max-width: 720px;
107	      margin-bottom: 28px;
108	    }
109	
110	    /* ---------- summary strip ---------- */
111	
112	    .summary {
113	      display: grid;
114	      grid-template-columns: repeat(4, 1fr);
115	      gap: 16px;
116	      margin-bottom: 64px;
117	    }
118	    @media (max-width: 900px) { .summary { grid-template-columns: repeat(2, 1fr); } }
119	    .summary .cell {
120	      background: var(--white);
121	      border: 1.5px solid var(--gray-300);
122	      border-radius: 12px;
123	      padding: 18px 20px;
124	    }
125	    .summary .k {
126	      font-family: var(--mono);
127	      font-size: 11px;
128	      text-transform: uppercase;
129	      letter-spacing: 0.06em;
130	      color: var(--gray-500);
131	      margin-bottom: 6px;
132	    }
133	    .summary .v {
134	      font-size: 17px;
135	      color: var(--slate);
136	      font-weight: 600;
137	    }
138	    .summary .v.accent { color: var(--clay); }
139	
140	    /* ---------- milestone timeline ---------- */
141	
142	    .milestones { display: flex; flex-direction: column; gap: 0; }
143	    .milestone {
144	      display: grid;
145	      grid-template-columns: 120px 28px 1fr;
146	      gap: 0 18px;
147	      position: relative;
148	    }
149	    .milestone .when {
150	      text-align: right;
151	      font-family: var(--mono);
152	      font-size: 12px;
153	      color: var(--gray-500);
154	      padding-top: 4px;
155	    }
156	    .milestone .dot-col {
157	      display: flex;
158	      flex-direction: column;
159	      align-items: center;
160	    }
161	    .milestone .dot {
162	      width: 14px; height: 14px;
163	      border-radius: 50%;
164	      background: var(--white);
165	      border: 3px solid var(--clay);
166	      margin-top: 4px;
167	      flex-shrink: 0;
168	    }
169	    .milestone .dot.done { background: var(--olive); border-color: var(--olive); }
170	    .milestone .line {
171	      width: 2px;
172	      flex: 1;
173	      background: var(--gray-300);
174	      margin: 4px 0;
175	    }
176	    .milestone:last-child .line { display: none; }
177	    .milestone .body { padding-bottom: 36px; }
178	    .milestone .body h3 {
179	      font-family: var(--serif);
180	      font-weight: 500;
181	      font-size: 19px;
182	      color: var(--slate);
183	      margin-bottom: 4px;
184	    }
185	    .milestone .body p { font-size: 14px; color: var(--gray-500); margin-bottom: 10px; max-width: 620px; }
186	    .milestone .tags { display: flex; gap: 8px; flex-wrap: wrap; }
187	    .milestone .tag {
188	      font-family: var(--mono);
189	      font-size: 11.5px;
190	      background: var(--gray-150);
191	      border: 1px solid var(--gray-300);
192	      border-radius: 6px;
193	      padding: 3px 8px;
194	      color: var(--gray-700);
195	    }
196	
197	    /* ---------- data flow diagram ---------- */
198	
199	    .diagram {
200	      background: var(--white);
201	      border: 1.5px solid var(--gray-300);
202	      border-radius: 12px;
203	      padding: 28px;
204	      overflow-x: auto;
205	    }
206	    .diagram svg { display: block; min-width: 760px; }
207	    .diagram text { font-family: var(--mono); }
208	    .caption { font-size: 13px; color: var(--gray-500); margin-top: 12px; }
209	
210	    /* ---------- mockups ---------- */
211	
212	    .mocks {
213	      display: grid;
214	      grid-template-columns: 1fr 1fr;
215	      gap: 28px;
216	    }
217	    @media (max-width: 900px) { .mocks { grid-template-columns: 1fr; } }
218	    .mock {
219	      background: var(--white);
220	      border: 1.5px solid var(--gray-300);
221	      border-radius: 12px;
222	      overflow: hidden;
223	    }
224	    .mock .mock-label {
225	      padding: 12px 18px;
226	      border-bottom: 1.5px solid var(--gray-300);
227	      font-family: var(--mono);
228	      font-size: 11.5px;
229	      text-transform: uppercase;
230	      letter-spacing: 0.06em;
231	      color: var(--gray-500);
232	      background: var(--gray-150);
233	    }
234	    .mock .mock-body { padding: 22px; }
235	
236	    /* task card mock */
237	    .card-mock {
238	      border: 1.5px solid var(--gray-300);
239	      border-radius: 10px;
240	      padding: 16px;
241	      background: var(--ivory);
242	    }
243	    .card-mock .cm-title { font-weight: 600; font-size: 15px; color: var(--slate); margin-bottom: 4px; }
244	    .card-mock .cm-meta { font-size: 12px; color: var(--gray-500); margin-bottom: 14px; }
245	    .card-mock .cm-divider { border-top: 1px dashed var(--gray-300); margin: 14px 0; }
246	    .thread { display: flex; flex-direction: column; gap: 12px; }
247	    .comment { display: flex; gap: 10px; }
248	    .comment .avatar {
249	      width: 26px; height: 26px; border-radius: 50%;
250	      background: var(--oat);
251	      flex-shrink: 0;
252	      display: flex; align-items: center; justify-content: center;
253	      font-size: 11px; font-weight: 600; color: var(--slate);
254	    }
255	    .comment .avatar.alt { background: var(--olive); color: var(--white); }
256	    .comment .bubble { flex: 1; }
257	    .comment .author { font-size: 12px; font-weight: 600; color: var(--slate); }
258	    .comment .author .time { font-weight: 400; color: var(--gray-500); margin-left: 6px; }
259	    .comment .text { font-size: 13px; color: var(--gray-700); margin-top: 2px; }
260	    .comment .reply-link { font-size: 11.5px; color: var(--clay); margin-top: 4px; cursor: default; }
261	    .comment.nested { margin-left: 36px; }
262	    .composer {
263	      display: flex; gap: 10px; align-items: center;
264	      margin-top: 6px;
265	    }
266	    .composer .field {
267	      flex: 1;
268	      border: 1.5px solid var(--gray-300);
269	      border-radius: 8px;
270	      padding: 8px 12px;
271	      font-size: 13px;
272	      color: var(--gray-500);
273	      background: var(--white);
274	    }
275	    .composer .send {
276	      background: var(--clay);
277	      color: var(--white);
278	      border-radius: 8px;
279	      padding: 8px 14px;
280	      font-size: 13px;
281	      font-weight: 600;
282	    }
283	
284	    /* sidebar digest mock */
285	    .digest { display: flex; flex-direction: column; gap: 10px; }
286	    .digest .row {
287	      display: flex; gap: 10px; align-items: flex-start;
288	      padding: 10px 12px;
289	      background: var(--ivory);
290	      border: 1.5px solid var(--gray-300);
291	      border-radius: 8px;
292	    }
293	    .digest .row.unread { border-left: 3px solid var(--clay); }
294	    .digest .mini-av {
295	      width: 22px; height: 22px; border-radius: 50%;
296	      background: var(--oat);
297	      flex-shrink: 0;
298	      font-size: 10px; font-weight: 600; color: var(--slate);
299	      display: flex; align-items: center; justify-content: center;
300	    }
301	    .digest .txt { font-size: 12.5px; color: var(--gray-700); line-height: 1.45; }
302	    .digest .txt strong { color: var(--slate); }
303	    .digest .txt .on { color: var(--gray-500); }
304	
305	    /* ---------- code panel ---------- */
306	
307	    .code-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 28px; }
308	    @media (max-width: 980px) { .code-grid { grid-template-columns: 1fr; } }
309	    .code-block { display: flex; flex-direction: column; gap: 10px; }
310	    .code-block .file-label {
311	      font-family: var(--mono);
312	      font-size: 12px;
313	      color: var(--gray-500);
314	    }
315	    .code {
316	      background: var(--slate);
317	      border-radius: 12px;
318	      padding: 18px 20px;
319	      overflow-x: auto;
320	      flex: 1;
321	    }
322	    .code pre {
323	      font-family: var(--mono);
324	      font-size: 12.5px;
325	      line-height: 1.65;
326	      color: #E8E6DE;
327	      white-space: pre;
328	    }
329	    .code .kw  { color: var(--clay); }
330	    .code .str { color: var(--olive); }
331	    .code .cm  { color: var(--gray-500); }
332	    .code .fn  { color: #C9B98A; }
333	
334	    /* ---------- risk table ---------- */
335	
336	    .risks {
337	      border: 1.5px solid var(--gray-300);
338	      border-radius: 12px;
339	      overflow: hidden;
340	      background: var(--white);
341	    }
342	    .risks .row {
343	      display: grid;
344	      grid-template-columns: 1.6fr 90px 1.6fr;
345	      gap: 0;
346	    }
347	    @media (max-width: 780px) { .risks .row { grid-template-columns: 1fr; } }
