1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Portable Nestl — Implementation plan</title>
7	<style>
8	  :root {
9	    --bg: #fcfcfd; --surface: #ffffff;
10	    --fg: #0a0a0f; --fg-soft: #2e2e38; --muted: #5f5f6a;
11	    --rule: #e3e3ea; --rule-soft: #f1f1f5;
12	    --accent: #4a3bef; --accent-soft: #efedff;
13	    --ok: #047a44;     --ok-soft: #e6f5ed;
14	    --info: #1957c4;   --info-soft: #e7f0fd;
15	    --warn: #8b4a05;   --warn-soft: #fbf0e0;
16	    --danger: #a82a3f; --danger-soft: #fbe6ea;
17	  }
18	  @media (prefers-color-scheme: dark) {
19	    :root {
20	      --bg: #0c0c10; --surface: #15151b;
21	      --fg: #f4f4f7; --fg-soft: #d6d6dd; --muted: #9d9dab;
22	      --rule: #2a2a33; --rule-soft: #1c1c24;
23	      --accent: #a99dff; --accent-soft: #251e4d;
24	      --ok: #6fd4a0;     --ok-soft: #143324;
25	      --info: #8eb8ff;   --info-soft: #122544;
26	      --warn: #f0a35a;   --warn-soft: #3a2410;
27	      --danger: #f08597; --danger-soft: #3d141c;
28	    }
29	  }
30	  * { box-sizing: border-box; }
31	  html, body { margin: 0; padding: 0; background: var(--bg); color: var(--fg-soft); }
32	  body {
33	    font: 16px/1.65 "Inter", ui-sans-serif, -apple-system, "Segoe UI", Roboto, sans-serif;
34	    font-feature-settings: "cv11","ss01","ss03","kern","liga";
35	    -webkit-font-smoothing: antialiased;
36	  }
37	  .shell { display: grid; grid-template-columns: 260px 1fr; min-height: 100vh; }
38	  aside {
39	    position: sticky; top: 0; align-self: start; height: 100vh; overflow-y: auto;
40	    background: var(--surface); border-right: 1px solid var(--rule);
41	    padding: 28px 24px;
42	  }
43	  .brand { display: flex; align-items: center; gap: 10px; margin-bottom: 28px; }
44	  .brand-dot { width: 28px; height: 28px; border-radius: 8px; background: linear-gradient(135deg, var(--accent), var(--info)); }
45	  .brand-name { font-weight: 700; font-size: 15px; color: var(--fg); letter-spacing: -0.01em; }
46	  .brand-kind { font: 11px ui-monospace, monospace; color: var(--muted); margin-top: 1px; letter-spacing: 0.04em; text-transform: uppercase; }
47	  .nav-kicker { font: 11px/1 "Inter", sans-serif; letter-spacing: 0.08em; text-transform: uppercase; color: var(--muted); margin: 22px 0 10px; font-weight: 700; }
48	  .nav { list-style: none; padding: 0; margin: 0; counter-reset: nav; }
49	  .nav li { counter-increment: nav; margin: 2px 0; }
50	  .nav a { display: flex; gap: 10px; padding: 7px 10px; border-radius: 6px; text-decoration: none; color: var(--fg-soft); font-size: 14.5px; align-items: center; }
51	  .nav a::before { content: counter(nav, decimal-leading-zero); font: 11px ui-monospace, monospace; color: var(--muted); }
52	  .nav a:hover { background: var(--rule-soft); color: var(--fg); }
53	  .status-block { margin-top: 28px; padding: 14px 14px; background: var(--bg); border: 1px solid var(--rule); border-radius: 8px; }
54	  .status-block .lbl { font: 11px ui-monospace, monospace; color: var(--muted); letter-spacing: 0.04em; text-transform: uppercase; }
55	  .status-block .val { font-size: 13.5px; color: var(--fg); margin-top: 4px; font-weight: 600; }
56	  main { padding: 56px 80px 120px; max-width: 980px; }
57	  .doc-head { margin-bottom: 32px; }
58	  .breadcrumbs { font: 13.5px ui-monospace, monospace; color: var(--muted); margin-bottom: 14px; letter-spacing: 0.02em; }
59	  h1 { font-size: 34px; line-height: 1.2; letter-spacing: -0.02em; color: var(--fg); margin: 0 0 16px; font-weight: 700; }
60	  .lede { font-size: 17.5px; line-height: 1.55; color: var(--fg-soft); margin: 0 0 20px; max-width: 70ch; }
61	  .pill-row { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 20px; }
62	  .pill { display: inline-flex; align-items: center; gap: 6px; font: 700 13px/1 "Inter", sans-serif; padding: 6px 10px; border-radius: 999px; letter-spacing: 0.02em; }
63	  .pill .dot { width: 7px; height: 7px; border-radius: 50%; background: currentColor; }
64	  .pill-draft { background: var(--info-soft); color: var(--info); }
65	  .pill-meta { background: var(--rule-soft); color: var(--muted); }
66	  .meta-grid { display: grid; grid-template-columns: max-content 1fr; column-gap: 18px; row-gap: 6px; font-size: 14px; margin: 0 0 28px; padding: 0; }
67	  .meta-grid dt { color: var(--muted); font: 11.5px ui-monospace, monospace; letter-spacing: 0.04em; text-transform: uppercase; padding-top: 2px; }
68	  .meta-grid dd { margin: 0; color: var(--fg-soft); font-size: 13.5px; }
69	  .meta-grid dd a { color: var(--accent); text-decoration: none; }
70	  /* P13 summary strip */
71	  .p-summary { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; margin: 0 0 36px; }
72	  .p-summary-cell { background: var(--surface); border: 1px solid var(--rule); border-radius: 10px; padding: 16px 18px; }
73	  .p-summary-k { font: 700 11px/1 "Inter", sans-serif; letter-spacing: 0.06em; text-transform: uppercase; color: var(--muted); margin-bottom: 8px; }
74	  .p-summary-v { font-size: 17px; font-weight: 600; color: var(--fg); line-height: 1.3; }
75	  .p-summary-v-accent { color: var(--accent); }
76	  @media (max-width: 720px) { .p-summary { grid-template-columns: repeat(2, 1fr); } }
77	  /* Sections */
78	  section.s { margin: 0 0 56px; scroll-margin-top: 24px; }
79	  section.s > header { display: flex; align-items: baseline; gap: 14px; margin: 0 0 14px; }
80	  section.s > header .ix { font: 12px ui-monospace, monospace; background: var(--rule-soft); color: var(--fg); padding: 4px 10px; border-radius: 6px; letter-spacing: 0.04em; }
81	  section.s > header h2 { margin: 0; font-size: 22px; font-weight: 700; color: var(--fg); letter-spacing: -0.01em; }
82	  .sec-intro { font-size: 14.5px; color: var(--muted); margin: 0 0 24px; max-width: 70ch; }
83	  /* Decision cards (architecture decisions reuse why-card shape) */
84	  .p-why-grid { display: grid; grid-template-columns: 1fr; gap: 14px; margin: 20px 0; }
85	  .p-why-card { background: var(--surface); border: 1px solid var(--rule); border-radius: 10px; padding: 18px 22px; transition: border-color 0.15s; }
86	  .p-why-card:hover { border-color: var(--accent); }
87	  .p-why-card h3 { margin: 0 0 8px; font-size: 16px; font-weight: 700; display: flex; align-items: center; gap: 10px; color: var(--fg); }
88	  .p-why-chev { font-size: 18px; line-height: 1; font-weight: 700; color: var(--accent); }
89	  .p-why-card p { margin: 0; font-size: 15px; color: var(--fg-soft); line-height: 1.6; }
90	  .p-why-card code { font-size: 0.92em; padding: 1px 5px; background: var(--rule-soft); border-radius: 3px; }
91	  /* P2 timeline */
92	  .p-timeline { list-style: none; padding: 0; margin: 16px 0; }
93	  .p-task { display: grid; grid-template-columns: 132px 28px 1fr; gap: 0 18px; }
94	  .p-task-when { text-align: right; font: 12.5px ui-monospace, monospace; color: var(--muted); padding-top: 6px; }
95	  .p-task-rail { display: flex; flex-direction: column; align-items: center; }
96	  .p-task-dot { width: 14px; height: 14px; border-radius: 50%; background: var(--bg); border: 3px solid var(--accent); margin-top: 6px; flex-shrink: 0; }
97	  .p-task-dot-done { background: var(--ok); border-color: var(--ok); }
98	  .p-task-dot-checkpoint { background: var(--warn); border-color: var(--warn); }
99	  .p-task-line { width: 2px; flex: 1; background: var(--rule); margin: 4px 0; }
100	  .p-task:last-child .p-task-line { display: none; }
101	  .p-task-body { padding-bottom: 28px; }
102	  .p-task-body h3 { margin: 0 0 6px; font-size: 17px; font-weight: 600; color: var(--fg); }
103	  .p-task-body h3 .p-task-size { font: 11px ui-monospace, monospace; background: var(--accent-soft); color: var(--accent); padding: 3px 7px; border-radius: 4px; margin-left: 10px; vertical-align: 2px; letter-spacing: 0.02em; font-weight: 700; }
104	  .p-task-body p { font-size: 14.5px; color: var(--fg-soft); margin: 0 0 10px; line-height: 1.55; max-width: 65ch; }
105	  .p-task-deps { color: var(--muted); font-size: 13.5px; }
106	  .p-task-tags { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 10px; }
107	  .p-task-tag { font: 11.5px ui-monospace, monospace; background: var(--rule-soft); border: 1px solid var(--rule); border-radius: 6px; padding: 3px 8px; color: var(--fg-soft); }
108	  .p-task-ac { list-style: none; padding: 0; margin: 10px 0 0; }
109	  .p-task-ac li { position: relative; padding: 3px 0 3px 22px; font-size: 13.5px; color: var(--fg-soft); }
110	  .p-task-ac li::before { content: ""; position: absolute; left: 4px; top: 12px; width: 10px; height: 10px; border-radius: 2px; border: 1.5px solid var(--rule); background: var(--bg); }
111	  /* Checkpoint row */
112	  .p-checkpoint { background: var(--warn-soft); border-left: 4px solid var(--warn); border-radius: 0 10px 10px 0; padding: 14px 18px; margin: 0 0 24px 150px; }
113	  .p-checkpoint .ck-label { font: 11.5px ui-monospace, monospace; color: var(--warn); letter-spacing: 0.06em; text-transform: uppercase; font-weight: 700; margin-bottom: 6px; }
114	  .p-checkpoint ul { margin: 0; padding-left: 20px; font-size: 14px; color: var(--fg-soft); line-height: 1.55; }
115	  /* P17 risks */
116	  .p-risks { border: 1px solid var(--rule); border-radius: 12px; overflow: hidden; background: var(--surface); margin: 20px 0; }
117	  .p-risks-row { display: grid; grid-template-columns: 1.6fr 90px 1.6fr; }
118	  .p-risks-row + .p-risks-row { border-top: 1px solid var(--rule); }
119	  .p-risks-row > div { padding: 14px 18px; font-size: 14px; line-height: 1.55; color: var(--fg-soft); }
120	  .p-risks-row > div + div { border-left: 1px solid var(--rule); }
121	  .p-risks-head > div { background: var(--rule-soft); color: var(--fg); font: 700 12px/1 "Inter", sans-serif; letter-spacing: 0.05em; text-transform: uppercase; padding: 12px 18px; }
122	  .p-sev { display: inline-block; font: 700 11px/1 ui-monospace, monospace; padding: 4px 9px; border-radius: 6px; letter-spacing: 0.04em; }
123	  .p-sev-high { background: var(--danger-soft); color: var(--danger); }
124	  .p-sev-med  { background: var(--warn-soft);   color: var(--warn); }
125	  .p-sev-low  { background: var(--ok-soft);     color: var(--ok); }
126	  /* P5 questions */
127	  .p-questions { display: flex; flex-direction: column; gap: 14px; margin: 20px 0; max-width: 820px; }
128	  .p-q { background: var(--surface); border: 1px solid var(--rule); border-left: 4px solid var(--accent); border-radius: 10px; padding: 16px 20px; }
129	  .p-q-title { font-weight: 600; font-size: 15.5px; color: var(--fg); margin-bottom: 6px; }
130	  .p-q-body { font-size: 14px; color: var(--fg-soft); line-height: 1.55; }
131	  .p-q-body code { font-size: 0.92em; padding: 1px 5px; background: var(--rule-soft); border-radius: 3px; }
132	  /* Footer */
133	  footer { border-top: 1px solid var(--rule); padding-top: 20px; margin-top: 60px; font-size: 13px; color: var(--muted); }
134	  footer code { font: 12px ui-monospace, monospace; }
135	  /* Inline code in prose */
136	  p code, li code { font-size: 0.92em; padding: 1px 5px; background: var(--rule-soft); border-radius: 3px; color: var(--fg); }
137	  /* Links — global default; nav and meta-grid override below */
138	  main a { color: var(--accent); text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 3px; text-decoration-color: color-mix(in srgb, var(--accent) 45%, transparent); }
139	  main a:hover { text-decoration-color: var(--accent); }
140	  @media (max-width: 1000px) {
141	    .shell { grid-template-columns: 1fr; }
142	    aside { display: none; }
143	    main { padding: 28px 24px 80px; }
144	    .p-task, .p-checkpoint { grid-template-columns: 22px 1fr; margin-left: 0; }
145	    .p-task-when { display: none; }

